// ShowMsg.java
import java.applet.Applet;
import java.awt.Graphics;
public class ShowMsg extends Applet {
  String msg;
  public void init() {
    msg = getParameter("msg");
    if (msg == null) msg = "欢迎";
  }
  public void paint(Graphics g) {
    g.drawString(msg, 30, 40);
  }
}

